#!/usr/bin/env bash
# Store > Cloud > Apps categories ARE the SuperApp's Cloud > Apps tile groups.
#
# One declaration: aa_cloud-superapp/build.json ui.sections[id=cloud].tile_groups. The Store's
# categories (constellation-fleet.json::app_categories, generated by data/regen.sh through
# data/app-categories.py) must equal it: same names, same order, each app in the group whose tile
# opens it, the rest in a declared last "Other". This test derives the expectation itself, with
# jq and not with the generator, so a generator that drifted from the page is caught here.
#
#   T1 category names + order equal the tile groups (that hold a fleet app), Other last
#   T2 membership equals: every app of the Cloud > Apps tab is in exactly the category its tile is in
#   T3 the Store page reads app_categories and has no category table of its own
#   T4 MUTATION: moving one app / swapping two categories / dropping Other makes T1/T2 fail
set -u
APP="$(cd "$(dirname "$0")/.." && pwd)"
FLEET="$APP/data/constellation-fleet.json"
BUILD="$APP/build.json"
PAGE="$APP/../ab_cloud-libs-shared/libs/appstore/src/main/java/com/diegonmarcos/superapp/appstore/StoreCloudFragment.kt"
PASS=0; FAIL=0
ok()  { PASS=$((PASS+1)); echo "  PASS: $1"; }
bad() { FAIL=$((FAIL+1)); echo "  FAIL: $1"; }
for f in "$FLEET" "$BUILD" "$PAGE"; do [ -f "$f" ] || { echo "ERROR: missing $f" >&2; exit 2; }; done
command -v jq >/dev/null || { echo "ERROR: jq required" >&2; exit 2; }

# expected: [{label, members:[fleet ids]}] from the tile groups alone (first tile wins), then Other.
expected() {  # $1 = fleet file
  jq -c --slurpfile fleet "$1" '
    ([ $fleet[0].apps[] | select(.package != null) | { key: .package, value: .id } ] | from_entries) as $byPkg
    | ([ (.ui.external_apps // [])[] | { key: .id, value: .install_package } ] | from_entries) as $ext
    | [ $fleet[0].groups[] | select(.id == "apps") | .members[] ] as $tab
    | [ (.ui.sections[] | select(.id == "cloud") | .tile_groups[]) as $g
        | { label: $g.title,
            ids: [ $g.tiles[]
                   | (.fleet_app // ( (.target // "") as $t
                       | if ($t | startswith("extapp:")) then $byPkg[ $ext[ ($t | ltrimstr("extapp:") | sub("#.*$"; "")) ] // "" ]
                         elif ($t | startswith("app://")) then $byPkg[ $t | ltrimstr("app://") ]
                         else null end ))
                   | select(. != null and IN($tab[])) ] } ] as $groups
    | ($groups | reduce .[] as $g ([]; . as $acc
         | ([ $acc[].members[] ]) as $seen
         | $acc + [{label: $g.label, members: ([ $g.ids[] | select(IN($seen[]?) | not) ] | reduce .[] as $i ([]; if IN(.[]; $i) then . else . + [$i] end))}])) as $filed
    | ($filed | map(select(.members | length > 0)))
      + [{label: "Other", members: [ $tab[] | select(IN($filed[].members[]) | not) ]}]
  ' "$BUILD" 2>/dev/null
}
actual() { jq -c '[ .app_categories[] | {label, members} ]' "$1"; }

check() {  # $1 = fleet file; prints FAIL reasons, returns 1 on any
  local f="$1" e a rc=0
  e="$(expected "$f")"; a="$(actual "$f")"
  if [ "$(jq -c 'map(.label)' <<<"$e")" != "$(jq -c 'map(.label)' <<<"$a")" ]; then
    echo "names/order differ: expected $(jq -c 'map(.label)' <<<"$e") got $(jq -c 'map(.label)' <<<"$a")"; rc=1; fi
  if [ "$(jq -c 'map(.members | sort)' <<<"$e")" != "$(jq -c 'map(.members | sort)' <<<"$a")" ]; then
    echo "membership differs: $(jq -nc --argjson e "$e" --argjson a "$a" '[range(0; ([$e,$a]|map(length)|max)) as $i | select(($e[$i].members // [] | sort) != ($a[$i].members // [] | sort)) | {category: ($e[$i].label // $a[$i].label)}]')"; rc=1; fi
  if [ "$(jq -c 'map(.members)' <<<"$e")" != "$(jq -c 'map(.members)' <<<"$a")" ]; then
    echo "order inside a category differs from the tile order"; rc=1; fi
  return $rc
}

echo "== T1/T2: the Store's categories equal the SuperApp's Cloud > Apps tile groups =="
if [ "$(jq -c 'length' <<<"$(expected "$FLEET")")" -lt 3 ]; then bad "could not derive the expectation from tile_groups"; fi
out="$(check "$FLEET")" && ok "app_categories == tile_groups: same names, same order, same membership, Other last" \
  || bad "app_categories differ from the tile groups - rerun aa_cloud-superapp/data/regen.sh --constellation-only: $out"
[ "$(jq -r '.app_categories[-1].label' "$FLEET")" = "Other" ] && ok "the last category is the declared Other" || bad "last category is not Other"
dupe="$(jq -r '[.app_categories[].members[]] | group_by(.)[] | select(length > 1) | .[0]' "$FLEET")"
[ -z "$dupe" ] && ok "no app is in two categories" || bad "in two categories: $dupe"
unf="$(jq -r '[.app_categories[].members[]] as $f | (.groups[] | select(.id == "apps") | .members[]) | select(IN($f[]) | not)' "$FLEET")"
[ -z "$unf" ] && ok "every app of the Cloud > Apps tab is in a category" || bad "unfiled: $unf"

echo "== T3: the Store page has no category table of its own =="
grep -qF 'fleetObjects("app_categories")' "$PAGE" && ok "the page reads app_categories" || bad "the page does not read app_categories"
if grep -nE 'AppStoreHost\.classify\(|PhoneTaxonomy|phone_sections|StoreJev' "$PAGE" >/dev/null; then bad "the page files apps by another source (classify / PhoneTaxonomy / Jev)"; else ok "no second classifier on the Cloud page"; fi
lits="$(jq -r '.app_categories[] | select(.id != "other") | .label, .id' "$FLEET" | sort -u)"
hard=""; while IFS= read -r l; do [ -n "$l" ] && grep -qF "\"$l\"" "$PAGE" && hard="$hard $l"; done <<<"$lits"
[ -z "$hard" ] && ok "no category label/id is written in the page" || bad "hardcoded in the page:$hard"

echo "== T4: mutations of the generated file must turn the check red =="
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
mut() {  # $1 name  $2 jq filter
  jq -c "$2" "$FLEET" > "$T/m.json"
  if check "$T/m.json" >/dev/null; then bad "MUTATION NOT CAUGHT: $1"; else ok "mutation caught: $1"; fi
}
mut "an app moved to another category" '.app_categories[0].members as $m | .app_categories[1].members += [$m[0]] | .app_categories[0].members = $m[1:]'
mut "two categories swapped" '.app_categories[0] as $a | .app_categories[1] as $b | .app_categories[0] = $b | .app_categories[1] = $a'
mut "a category renamed" '.app_categories[0].label = "Inbox"'
mut "Other dropped" '.app_categories |= .[:-1]'
mut "two apps swapped inside a category" '.app_categories[1].members |= ([.[1], .[0]] + .[2:])'

echo "passed $PASS, failed $FAIL"
[ "$FAIL" -eq 0 ]
